  "slug": "customer-ledger-month-end-checklist",
  "title": "Month-End Checklist Before Sharing a Customer Ledger",
  "description": "Check the company, period, movements and balances before sending a ledger PDF to a customer.",
  "category": "Ledgers and PDFs",
  "sections": [
    {
      "heading": "Set the reporting period",
      "body": "Open the intended customer ledger in the correct company and set the period you agreed to share. Check that the party name matches the customer's records, especially when there are several similar names."
    },
    {
      "heading": "Tie the statement back to TallyPrime",
      "body": "Compare opening balance, debit and credit activity and closing balance with the original ledger. Review recent receipts, refund entries or credit notes separately when the ending amount differs. An item dated just after the period closes will be visible in the next statement period."
    },
    {
      "heading": "Open the PDF before sending",
      "body": "Read the header and confirm the company, customer and date range. Check a recent transaction and the displayed closing balance. If a balance is missing or unverified, compare it with TallyPrime and resolve the discrepancy before sending."
    }
  ],
  "relatedPaths": [
    "/guides/tally-ledger-on-mobile",
    "/for-accountants"
  ]
}
